<script lang="ts">
 import {onMount,tick} from 'svelte';
 import {GitCompareArrows,Layers3,Box,Scale,Settings2,Activity,FolderOpen,ArrowRightLeft,Play,Plus,Square,Check,AlertTriangle,Search,Sun,Moon,ExternalLink,Download,ChevronRight,RotateCcw,FileBox,X,Info} from 'lucide-svelte';
 import Numeric from './Numeric.svelte';
 import About from './About.svelte';
 import ResultsWorkspace from './ResultsWorkspace.svelte';
 import ProgressPanel from './ProgressPanel.svelte';
 import {version} from '../package.json';
 let aboutOpen=$state(false);
 import {defaults,validate,statuses,paletteKeys,paletteLabels,restorePalette,fileName,type Settings,type Job,type Summary,stepPaths,massSummary,hasTranslation} from './model';
 import {call,pick,start,native,watchDrops} from './api';
 let tab=$state('compare'),a=$state(''),b=$state(''),massFiles=$state<string[]>([]);
 let settings=$state<Settings>(structuredClone(defaults));let saved=$state<Settings>(structuredClone(defaults));
 let activeMode=$state(''),job=$state<Job|null>(null),summary=$state<Summary|null>(null),resultFolder=$state(''),auxFolder=$state(''),notice=$state(''),error=$state(''),busy=$state(false),engineReady=$state(false),polling=false;
 let elapsed=$state(0),startedAt=0;
 const autoReviewTokens=new Set<string>();let massResult=$state<ReturnType<typeof massSummary>>(null),massFolder=$state(''),dropRole=$state(''),dismissedJob='',massInputKey='';
 $effect(()=>{const key=JSON.stringify({files:[...massFiles],density:settings.density});if(massResult&&key!==massInputKey)massResult=null;});
 const running=$derived(job?.running===true);
 const nav=[{id:'compare',label:'Porównanie',icon:GitCompareArrows},{id:'mass',label:'Masa części',icon:Scale}];
 const controls=[{id:'step',label:'Kolorowy model STEP'},{id:'preview',label:'Interaktywny podgląd 3D'},{id:'bom',label:'Grupowane zestawienie BOM'},{id:'bomCsv',label:'BOM także jako CSV'},{id:'align',label:'Sprawdzaj przesunięcie całego złożenia'}] as const;
 function focusDialog(node:HTMLElement){const previous=document.activeElement as HTMLElement|null;queueMicrotask(()=>node.querySelector<HTMLButtonElement>('button')?.focus());const onKey=(e:KeyboardEvent)=>{if(e.key==='Tab'){const buttons=Array.from(node.querySelectorAll<HTMLElement>('button,summary,[tabindex]')).filter(x=>!(x as HTMLButtonElement).disabled);const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};node.addEventListener('keydown',onKey);return{destroy(){node.removeEventListener('keydown',onKey);previous?.focus()}}}
 function fail(e:unknown){error=String(e);}
 async function choose(role:'a'|'b'|'mass'|'output'){try{const p=await pick(role==='output',role==='mass');if(!p.length)return;if(role==='a')a=p[0];else if(role==='b')b=p[0];else if(role==='mass')massFiles=[...new Set([...massFiles,...p])];else settings.output=p[0];}catch(e){fail(e)}}
 async function run(mode='compare'){error='';notice='';autoReviewTokens.clear();activeMode=mode;if(mode==='mass'){massResult=null;massInputKey=JSON.stringify({files:[...massFiles],density:settings.density});}const problem=validate(settings);if(problem){error=problem;return;}busy=true;try{job=await start(mode,mode==='compare'?[a,b]:mode==='mass'?massFiles:[],structuredClone($state.snapshot(settings)));startedAt=Date.now();elapsed=0;}catch(e){fail(e)}finally{busy=false}}
 async function poll(){if(polling||!native)return;polling=true;try{const next=await call<Job|null>('poll_job');if(next&&next.id!==dismissedJob){
    if(next.running&&next.question?.material_unverified){
      const token=next.question.token;
      if(!autoReviewTokens.has(token)){
        autoReviewTokens.add(token);
        try{
          await call('answer_question',{token,decision:'review'});
          notice='Zapisuję automatycznie raport częściowy. Niepotwierdzone części pozostaną oznaczone jako „Do sprawdzenia”.';
        }catch(e){autoReviewTokens.delete(token);fail(e)}
      }
      // Never display the partial-report confirmation dialog.
      next.question=null;
    }
    const finished=job?.running&&!next.running;job=next;if(next.running&&startedAt)elapsed=Math.floor((Date.now()-startedAt)/1000);if(finished){if(next.error)error=next.error;else if(next.cancelled)notice='Analiza anulowana. Poprzednie wyniki pozostają dostępne.';else if(next.summary){summary=next.summary;resultFolder=next.folder;tab='compare';void revealResults();}else{notice='Operacja zakończona.';auxFolder=next.folder;if(next.result?.podsumowanie){massResult=massSummary(next.result.podsumowanie);massFolder=next.folder;notice=massResult?'':'Zestawienie mas jest gotowe.';}}}}}catch(e){fail(e)}finally{polling=false}}
 async function cancel(){try{await call('cancel_job');await poll();}catch(e){fail(e)}}
 async function answer(decision:string){if(!job?.question)return;busy=true;try{await call('answer_question',{token:job.question.token,decision});job={...job,question:null};}catch(e){fail(e)}finally{busy=false}}
 async function save(){const problem=validate(settings);if(problem){error=problem;return;}try{await call('save_settings',{settings:structuredClone($state.snapshot(settings))});saved=structuredClone($state.snapshot(settings));notice='Ustawienia zapisane.';}catch(e){fail(e)}}
 async function openResult(){notice='';try{const p=await pick(true);if(!p.length)return;const s=await call<Summary>('load_result',{folder:p[0]});summary=s;resultFolder=p[0];tab='compare';void revealResults();}catch(e){fail(e)}}
 async function revealResults(){await tick();document.getElementById('compare-results')?.scrollIntoView({block:'start',behavior:'smooth'});}
 async function output(name:string){try{await call('open_artifact',{folder:name==='RAPORT_MASY.html'?massFolder||auxFolder:resultFolder||job?.folder,name});}catch(e){fail(e)}}
 function theme(){settings.theme=settings.theme==='dark'?'light':'dark';}
 function newComparison(){if(running||busy)return;autoReviewTokens.clear();dismissedJob=job?.id||dismissedJob;job=null;a='';b='';summary=null;resultFolder='';error='';notice='';elapsed=0;tab='compare';}
 function dropTarget(position?:{x:number;y:number}){if(!position)return '';return document.elementFromPoint(position.x/window.devicePixelRatio,position.y/window.devicePixelRatio)?.closest<HTMLElement>('[data-drop-role]')?.dataset.dropRole||'';}
 function dropped(paths:string[],role:string){if(running||busy)return;try{const valid=stepPaths(paths);if(role==='mass'||tab==='mass'){massFiles=[...new Set([...massFiles,...valid])];return;}if(tab!=='compare')return;if(valid.length>2)throw Error('Do porównania wybierz jeden lub dwa pliki STEP.');if(valid.length===2){[a,b]=valid;}else if(role==='b'||(!role&&a)){b=valid[0];}else a=valid[0];error='';}catch(e){fail(e)}}
 onMount(()=>{let alive=true;let unlisten:(()=>void)|undefined;(async()=>{if(!native)return;try{const [s,env]=await Promise.all([call<Settings|null>('load_settings'),call<{engine_ready:boolean}>('environment')]);if(alive){if(s){settings={...structuredClone(defaults),...s,palette:restorePalette(s.palette)};saved=structuredClone($state.snapshot(settings));}engineReady=env.engine_ready;}}catch(e){fail(e)}let dragReady=false;try{const stop=await watchDrops(e=>{if(!alive)return;if(e.type==='leave'){dropRole='';return;}const target=dropTarget(e.position);if(e.type==='drop'){dropped(e.paths||[],target);dropRole='';}else dropRole=target;});dragReady=true;if(alive)unlisten=stop;else stop();}catch(e){fail(e)}try{await call('startup_ready',{dragDropReady:dragReady})}catch(e){fail(e)}})();const timer=setInterval(poll,750);return()=>{alive=false;clearInterval(timer);unlisten?.()}});
</script>
<svelte:head><title>DS Compare · Porównanie rewizji CAD</title></svelte:head>
<div class="app" data-theme={settings.theme}>
 <aside class="rail"><div class="brand"><span class="brand-mark"><Layers3 size={24}/></span><div>DS Compare</div></div><nav>{#each nav as n}<button class:active={tab===n.id} onclick={()=>{tab=n.id;notice=''}}><n.icon size={19}/>{n.label}</button>{/each}</nav><div class="rail-bottom"><button onclick={()=>aboutOpen=true}><Info size={18}/>O programie</button><button class:active={tab==='diagnostic'} onclick={()=>tab='diagnostic'}><Activity size={18}/>Diagnostyka</button><button class:active={tab==='settings'} onclick={()=>tab='settings'}><Settings2 size={18}/>Ustawienia</button><div class="engine-state technical-only"><i class:ready={engineReady}></i><span>{native?engineReady?'Silnik CAD gotowy':'Brak pakietu silnika':'Podgląd interfejsu WWW'}</span></div></div></aside>
 <div class="workspace"><header><div class="breadcrumb"><strong>{nav.find(n=>n.id===tab)?.label|| (tab==='settings'?'Ustawienia':'Diagnostyka')}</strong></div><div class="header-actions"><button class="subtle" onclick={openResult}><FolderOpen size={16}/>Otwórz wyniki</button><button class="icon-button" aria-label="Zmień motyw" onclick={theme}>{#if settings.theme==='dark'}<Sun size={18}/>{:else}<Moon size={18}/>{/if}</button></div></header>
 <main>
 {#if !native}<div class="banner info">Podgląd nowego interfejsu. Analiza CAD i wybór plików działają w aplikacji desktopowej Tauri.</div>{/if}
 {#if error}<div class="banner danger" role="alert"><AlertTriangle size={18}/><div><strong>Operacja nie została ukończona</strong><p>{error.length>240||error.includes('Traceback')?'Nie udało się ukończyć operacji. Sprawdź szczegóły błędu.':error}</p>{#if error.length>240||error.includes('Traceback')}<details><summary>Szczegóły błędu</summary><pre>{error}</pre></details>{/if}</div><button aria-label="Zamknij komunikat" onclick={()=>error=''}><X size={16}/></button></div>{/if}
 {#if notice}<div class="banner info" role="status">{notice}<button aria-label="Zamknij informację" onclick={()=>notice=''}><X size={16}/></button></div>{/if}
 {#if tab==='compare'}
 <div class="page-heading"><div><span class="eyebrow">PORÓWNANIE MODELI</span><h1>Porównaj modele</h1><p>Wybierz lub przeciągnij dwa pliki STEP.</p></div></div>
 <div class="compare-grid"><button data-drop-role="a" class:drop-active={dropRole==='a'} class="file-card" disabled={running} onclick={()=>choose('a')}><span class="file-letter">A</span><span class="file-card-icon"><FileBox size={34}/></span><span class="eyebrow">POPRZEDNIA REWIZJA</span><strong>{a?fileName(a):'Wybierz model A'}</strong><span class="file-path">{a||'Przeciągnij tutaj plik STEP'}</span><span class="file-pick"><FolderOpen size={15}/>{a?'Zmień plik':'Wybierz plik'}</span></button><button class="swap" aria-label="Zamień modele A i B" disabled={running} onclick={()=>{const old=a;a=b;b=old}}><ArrowRightLeft size={20}/></button><button data-drop-role="b" class:drop-active={dropRole==='b'} class="file-card file-new" disabled={running} onclick={()=>choose('b')}><span class="file-letter">B</span><span class="file-card-icon"><FileBox size={34}/></span><span class="eyebrow">NOWA REWIZJA</span><strong>{b?fileName(b):'Wybierz model B'}</strong><span class="file-path">{b||'Przeciągnij tutaj plik STEP'}</span><span class="file-pick"><FolderOpen size={15}/>{b?'Zmień plik':'Wybierz plik'}</span></button></div>
 <details class="comparison-options"><summary>Opcje porównania</summary> <div class="analysis-options panel"><div><h2>Dokładność analizy</h2><p>Tolerancja geometryczna używana do weryfikacji modeli.</p></div><Numeric bind:value={settings.tolerance} step={.001} min={.000001} max={10} label="Tolerancja geometryczna" unit="mm" disabled={running}/><button class="subtle" onclick={()=>tab='settings'}>Wszystkie ustawienia<ChevronRight size={15}/></button></div>
 <div class="panel exports"><div><h2>Wyniki porównania</h2><p>Raport zmian powstaje przy każdej ukończonej analizie.</p></div><div class="checkbox-grid">{#each controls as c}<label><input type="checkbox" bind:checked={settings[c.id]} disabled={running}/>{c.label}</label>{/each}</div></div>
</details>
 <div class="start-row"><div class="muted"><Box size={17}/>Oryginalne pliki pozostają bez zmian.</div><div class="compare-actions"><button class="primary" disabled={!native||!engineReady||!a||!b||running||busy} onclick={()=>run()}><Play size={17}/>Porównaj rewizje</button><button class="subtle new-comparison" disabled={running||busy} onclick={newComparison}><Plus size={16}/>Nowe porównanie</button></div></div>
 {#if job && running && activeMode==='compare'}
  <ProgressPanel {job} {elapsed} oncancel={cancel}/>
 {:else if summary && resultFolder}
  <section id="compare-results" class="inline-results" aria-label="Wyniki porównania">
   <ResultsWorkspace {summary} folder={resultFolder} {settings} onerror={fail} onopen={openResult} onpreview={()=>{}}/>
  </section>
 {/if}
 {:else if tab==='settings'}
 <div class="page-heading"><div><span class="eyebrow">KONFIGURACJA</span><h1>Ustawienia analizy</h1><p>Zmiany dotyczą kolejnej analizy. Zapisz ustawienia, aby użyć ich po ponownym uruchomieniu.</p></div></div>
 <fieldset disabled={running} class="settings-grid"><section class="panel"><h2>Geometria i masa</h2><label class="setting">Tolerancja<Numeric bind:value={settings.tolerance} step={.001} min={.000001} max={10} label="Tolerancja" unit="mm"/></label><label class="setting">Gęstość materiału<Numeric bind:value={settings.density} step={50} min={1} label="Gęstość materiału" unit="kg/m³"/></label><p class="hint">Masa wynika z objętości i podanej gęstości. STEP nie musi zawierać materiału.</p><label class="setting">Limit brył<Numeric bind:value={settings.maxSolids} step={1000} min={1} max={1000000} label="Limit brył"/></label><label class="check"><input type="checkbox" bind:checked={settings.align}/>Wykrywaj przesunięcie całego złożenia</label><p class="hint">Program poprosi o decyzję przed wyrównaniem modeli.</p></section><section class="panel"><h2>Raport i eksport</h2><label class="stacked">Folder wyników<div class="input-action"><input bind:value={settings.output} placeholder="Dokumenty / DSCompare"/><button class="icon-button" aria-label="Wybierz folder wyników" onclick={()=>choose('output')}><FolderOpen size={17}/></button></div></label>{#each controls.slice(0,4) as c}<label class="check"><input type="checkbox" bind:checked={settings[c.id]}/>{c.label}</label>{/each}<label class="setting">Nieprzezroczystość starej A<Numeric bind:value={settings.oldAlpha} step={.05} min={0} max={1} label="Nieprzezroczystość starej wersji A"/></label><p class="hint">0 = całkowicie przezroczysta, 1 = nieprzezroczysta.</p></section><section class="panel"><h2>Kolory modeli</h2><div class="colors">{#each paletteKeys as key}<label><input type="color" bind:value={settings.palette[key]} aria-label={`Kolor: ${paletteLabels[key]}`}/>{paletteLabels[key]||statuses[key.toUpperCase()]||key}</label>{/each}</div><p class="hint">10 niezależnych kategorii w 5 parach — zgodnych z filtrami HTML 3D. Materiał dodany, usunięty i wspólny mają własne kolory, niezależne od całych części.</p><button class="subtle" onclick={()=>settings.palette=structuredClone(defaults.palette)}><RotateCcw size={15}/>Przywróć paletę</button></section><details class="panel advanced-export"><summary>Zaawansowany eksport STEP</summary><label class="setting">Standard<select bind:value={settings.schema}><option>AP214IS</option><option>AP242DIS</option></select></label><label class="setting">Weryfikacja<select bind:value={settings.verify}><option value="auto">Automatyczna</option><option value="full">Pełna</option><option value="fast">Szybka</option></select></label><label class="check"><input type="checkbox" bind:checked={settings.flat}/>Płaski STEP bez podzłożeń</label><label class="check"><input type="checkbox" bind:checked={settings.bodyColors}/>Kolorowanie na poziomie brył</label><label class="check"><input type="checkbox" bind:checked={settings.diffStep}/>Osobny STEP różnic materiału</label><label class="check"><input type="checkbox" bind:checked={settings.fastBom}/>Szybkie grupowanie BOM</label></details></fieldset><div class="start-row"><button onclick={()=>{settings=structuredClone($state.snapshot(saved));notice='Przywrócono zapisane ustawienia.'}}><RotateCcw size={16}/>Cofnij zmiany</button><button class="primary" disabled={running||!native} onclick={save}><Check size={17}/>Zapisz ustawienia</button></div>
 {:else if tab==='mass'}
 <div class="page-heading"><div><span class="eyebrow">OBJĘTOŚĆ I GĘSTOŚĆ</span><h1>Masa części i złożeń</h1><p>Oblicz masę jednego modelu lub zestawienia wielu plików STEP.</p></div><button disabled={running} onclick={()=>choose('mass')}><FolderOpen size={16}/>Dodaj modele</button></div>{#if massResult}<section class="mass-result panel" aria-label="Wynik obliczenia masy"><p>Łączna masa</p><strong>{massResult.mass.toLocaleString('pl',{maximumFractionDigits:3})} <small>kg</small></strong><p>Modele: {massResult.models} · Bryły: {massResult.solids} · Gęstość: {massResult.density.toLocaleString('pl')} kg/m³</p><button onclick={()=>output('RAPORT_MASY.html')}>Otwórz zestawienie HTML</button></section>{/if}<section class="panel mass-drop" data-drop-role="mass" class:drop-active={dropRole==='mass'}><div class="setting">Gęstość<Numeric bind:value={settings.density} min={1} step={50} label="Gęstość do obliczenia masy" unit="kg/m³" disabled={running}/></div>{#if massFiles.length}<ul class="file-list">{#each massFiles as f}<li><FileBox size={18}/><span title={f}>{fileName(f)}</span><button aria-label={`Usuń ${fileName(f)}`} disabled={running} onclick={()=>massFiles=massFiles.filter(x=>x!==f)}><X size={16}/></button></li>{/each}</ul>{:else}<div class="empty"><Scale size={40}/><p>Przeciągnij tutaj pliki STEP lub wybierz „Dodaj modele”.</p></div>{/if}<div class="start-row"><button disabled={running} onclick={()=>massFiles=[]}>Wyczyść listę</button><button class="primary" disabled={!native||!engineReady||!massFiles.length||running||busy} onclick={()=>run('mass')}><Play size={16}/>Oblicz masę</button></div></section>
 {:else if tab==='diagnostic'}
 <div class="page-heading"><div><span class="eyebrow">KONTROLA DZIAŁANIA</span><h1>Diagnostyka lokalna</h1><p>Testy silnika tworzą własny folder wyników. Nie zmieniają Twoich modeli.</p></div><button class="primary" disabled={!native||!engineReady||running||busy} onclick={()=>run('diagnostic')}><Activity size={17}/>Uruchom testy</button></div><section class="panel"><h2>Ostatnie zdarzenia</h2><pre>{job?.events.join('\n')||'Brak zdarzeń.'}</pre>{#if job}<button onclick={()=>call('open_artifact',{folder:job?.folder,name:'folder'}).catch(fail)}><FolderOpen size={16}/>Folder diagnostyczny</button>{/if}</section>
 {/if}
 {#if job&&running&&(activeMode!=='compare'||tab!=='compare')}<ProgressPanel {job} {elapsed} oncancel={cancel}/>{/if}
 </main><footer><span>DS Compare · Desktop {version}</span><span>Twoje pliki pozostają na tym komputerze.</span></footer></div>
 {#if job?.question && !job.question.material_unverified}<div class="modal-backdrop"><div class="modal" use:focusDialog role="alertdialog" tabindex="-1" aria-modal="true" aria-labelledby="decision-title"><span class="modal-icon"><AlertTriangle size={27}/></span><h2 id="decision-title">{job.question.unrelated?'Sprawdź zgodność modeli':job.question.unresolved?'Czy modele mają wspólne położenie?':hasTranslation(job.question)?'Wyrównaj położenie modeli':'Sprawdź położenie modeli'}</h2>{#if hasTranslation(job.question)}<p>Proponowane przesunięcie B → A:</p><div class="translation">{#each ['X','Y','Z'] as axis,i}<span>{axis}<strong>{job.question.translation_mm[i]?.toFixed(4)} mm</strong></span>{/each}</div><p>Wybierz wyrównanie albo porównanie w oryginalnym położeniu.</p>{:else}<p>{job.question.unrelated?'Nie udało się potwierdzić dopasowania tych modeli. Sprawdź, czy wybrano właściwe pliki.':'Program nie potwierdził wspólnego położenia. Możesz poszukać wyrównania lub porównać modele tak, jak zostały zapisane.'}</p>{/if}<details><summary>Szczegóły techniczne</summary><pre>{job.question.reason}</pre></details><div class="modal-actions"><button disabled={busy} onclick={()=>answer('cancel')}>Przerwij</button><button disabled={busy} onclick={()=>answer('original')}>Oryginalne położenie</button>{#if !job.question.unrelated}<button class="primary" disabled={busy} onclick={()=>answer(job?.question?.unresolved?'search':'align')}>{job.question.unresolved?'Szukaj wyrównania':'Wyrównaj modele'}</button>{/if}</div></div></div>{/if}
 {#if aboutOpen}<About onclose={()=>aboutOpen=false}/>{/if}
</div>
